import{_ as n,a0 as s,w as i,s as c,ao as h,I as o,x as t,a1 as r,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"Linux常见问题与答案—如何在Apache网站服务器上关闭服务器签名 | LCTT x X-CMD","titleTemplate":false,"description":"Linux常见问题与答案—如何在Apache网站服务器上关闭服务器签名 | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux常见问题与答案—如何在Apache网站服务器上关闭服务器签名 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux常见问题与答案—如何在Apache网站服务器上关闭服务器签名 | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140813 Linux FAQs with Answers--How to turn off server signature on Apache web server","title":"Linux常见问题与答案—如何在Apache网站服务器上关闭服务器签名","tag":"201408","desc":""},"relativePath":"201408/20140813 Linux FAQs with Answers--How to turn off server signature on Apache web server.md","filePath":"[post].md"}'),u={name:"201408/20140813 Linux FAQs with Answers--How to turn off server signature on Apache web server.md"};function l(d,e,f,m,A,x){const p=s("Link");return i(),c("div",null,[e[11]||(e[11]=h(`<h1 id="linux常见问题与答案—如何在apache网站服务器上关闭服务器签名" tabindex="-1">Linux常见问题与答案—如何在Apache网站服务器上关闭服务器签名 <a class="header-anchor" href="#linux常见问题与答案—如何在apache网站服务器上关闭服务器签名" aria-label="Permalink to “Linux常见问题与答案—如何在Apache网站服务器上关闭服务器签名”">​</a></h1><blockquote><p><strong>问题</strong>：每当Apache2网站服务器返回错误页时（如，404 页面无法找到，403 禁止访问页面），它会在页面底部显示网站服务器签名（如，Apache版本号和操作系统信息）。同时，当Apache2网站服务器为PHP页面服务时，它也会显示PHP的版本信息。我如何在Apache2网站服务器上关闭这些网站服务器签名呢？</p></blockquote><p>透露网站服务器带有服务器/PHP版本信息的签名会带来安全隐患，因为你基本上将你系统上的已知漏洞告诉给了攻击者。因此，作为服务器加固的一个部分，强烈推荐你禁用所有网站服务器签名。</p><p><img src="https://farm4.staticflickr.com/3897/14902970545_c3d406322f_o.png" alt=""></p><h3 id="禁用apache网站服务器签名" tabindex="-1">禁用Apache网站服务器签名 <a class="header-anchor" href="#禁用apache网站服务器签名" aria-label="Permalink to “禁用Apache网站服务器签名”">​</a></h3><p>禁用Apache网站服务器签名可以通过编辑Apache配置文件来实现。</p><p>在Debian，Ubunt或者Linux Mint上：</p><pre><code>$ sudo vi /etc/apache2/apache2.conf
</code></pre><p>在CentOS，Fedora，RHEL或者Arch Linux上：</p><pre><code>$ sudo vi /etc/httpd/conf/httpd.conf
</code></pre><p>将下面两行添加到Apache配置文件底部。</p><blockquote><p>ServerSignature Off</p><p>ServerTokens Prod</p></blockquote><p>然后重启网站服务器以使修改生效：</p><pre><code>$ sudo service apache2 restart (Debian, Ubuntu or Linux Mint)
$ sudo service httpd restart (CentOS/RHEL 6)
$ sudo systemctl restart httpd.service (Fedora, CentOS/RHEL 7, Arch Linux)
</code></pre><p>第一行‘ServerSignature Off’使得Apache2网站服务器在所有错误页面上隐藏Apache版本信息。</p><p><img src="https://farm6.staticflickr.com/5556/14879982016_7c7b8bbf3d_o.png" alt=""></p><p>然而，若没有第二行的‘ServerTokens Prod’，Apache服务器将仍然在HTTP回应头部包含详细的服务器标记，这会泄漏Apache的版本号。</p><p><img src="https://farm4.staticflickr.com/3889/14902970535_e84ec23090_z.jpg" alt=""></p><p>第二行‘<strong>ServerTokens Prod</strong>’所要做的是在HTTP响应头中将服务器标记压缩到最小。</p><p>因此，同时放置两行时，Apache将不会在页面中或者HTTP响应头中泄漏版本信息。</p><p><img src="https://farm4.staticflickr.com/3902/14902970505_d79225f25d_z.jpg" alt=""></p><h3 id="隐藏php版本" tabindex="-1">隐藏PHP版本 <a class="header-anchor" href="#隐藏php版本" aria-label="Permalink to “隐藏PHP版本”">​</a></h3><p>另外一个潜在的安全威胁是HTTP响应头中的PHP版本信息泄漏。默认情况下，Apache网站服务器通过HTTP响应头中的“X-Powered-By”字段包含有PHP版本信息。如果你想要在HTTP头部中隐藏PHP版本，请使用文本编辑器打开php.ini文件，找到“expose_php = On”这一行，将它改为“expose_php = Off”即可。</p><p><img src="https://farm4.staticflickr.com/3853/14899917981_aaef71eb0a.jpg" alt=""></p><p>在Debian，Ubunt或者Linux Mint上：</p><pre><code>$ sudo vi /etc/php5/apache2/php.ini
</code></pre><p>在CentOS，Fedora，RHEL或者Arch Linux上：</p><pre><code>$ sudo vi /etc/php.ini
</code></pre><blockquote><p>expose_php = Off</p></blockquote><p>最后，重启Apache2网站服务器来重新加载已更新的PHP配置文件。</p><p>现在，你不会再看到带有“X-Powered-By”字段的HTTP响应头了。</p><hr>`,32)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),r(p,{href:"http://ask.xmodulo.com/turn-off-server-signature-apache-web-server.html"},{default:a(()=>[...e[0]||(e[0]=[t("http://ask.xmodulo.com/turn-off-server-signature-apache-web-server.html",-1)])]),_:1})]),o("p",null,[e[4]||(e[4]=t("译者：",-1)),r(p,{href:"https://github.com/GOLinux"},{default:a(()=>[...e[2]||(e[2]=[t("GOLinux",-1)])]),_:1}),e[5]||(e[5]=t(" 校对：",-1)),r(p,{href:"https://github.com/carolinewuyan"},{default:a(()=>[...e[3]||(e[3]=[t("Caroline",-1)])]),_:1})]),o("p",null,[e[8]||(e[8]=t("本文由 ",-1)),r(p,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原创翻译，",-1)),r(p,{href:"http://linux.cn/"},{default:a(()=>[...e[7]||(e[7]=[t("Linux中国",-1)])]),_:1}),e[10]||(e[10]=t(" 荣誉推出",-1))])])}const _=n(u,[["render",l]]);export{L as __pageData,_ as default};
